CREATE SEQUENCE IF NOT EXISTS Proj_Proj_Seq
  INCREMENT BY 1
  START WITH 1;

CREATE TABLE Proj_Proj                                   -- المشاريع
( Id          BIGINT NOT NULL,                           -- PK
  Cust_Id     BIGINT Default 0 NOT NULL,                 -- الزبون
  Type_Id     BIGINT Default 0 NOT NULL,                 -- نوع القضية
  Status_Id   BIGINT Default 1 NOT NULL,                 -- حالة القضية
  Priority_Id BIGINT Default 0 NOT NULL,                 -- Priority
  Member_Id   BIGINT Default 0 NOT NULL,                 -- معرف الفريق
  Class1_Id   BIGINT Default 0 NOT NULL,                 -- تصنيف 1
  Class2_Id   BIGINT Default 0 NOT NULL,                 -- تصنيف 2
  Class3_Id   BIGINT Default 0 NOT NULL,                 -- تصنيف 3
  Curn_Id     BIGINT Default 1 NOT NULL,                 -- العملة
  Progress    SMALLINT DEFAULT 0 NOT NULL,                 -- نسبة الإنجاز
  Name        VARCHAR(100) NOT NULL,                  -- الاسم
  SDate       TIMESTAMP NOT NULL,                                -- تاريخ البداية
  EDate       TIMESTAMP,                                         -- تاريخ النهاية
  ASDate      TIMESTAMP,                                         -- Start Date
  AEDate      TIMESTAMP,                                         -- End Date
  Rem         VARCHAR(100),                           -- ملاحظات
  Descr       VARCHAR(4000),                         
  Ins_User    BIGINT, Ins_Date     TIMESTAMP,
  Upd_User    BIGINT, Upd_Date     TIMESTAMP,
  CONSTRAINT  Proj_Proj_PK          PRIMARY KEY (Id  ),
  CONSTRAINT  Proj_Proj_UK          UNIQUE      (Name)
);

