CREATE SEQUENCE IF NOT EXISTS Proj_Proj_TSheet_Seq
  INCREMENT BY 1
  START WITH 1;

CREATE TABLE Proj_Proj_TSheet                        -- أعمال مشروع
( Id         BIGINT NOT NULL,                           -- PK
  Proj_Id    BIGINT NOT NULL,                           -- المشروع
  Team_Id    BIGINT NOT NULL,                           -- عضو المشروع
  MWItem_Id  BIGINT NOT NULL,                           -- مجموعة الأعمال
  TWItem_Id  BIGINT NOT NULL,                           -- بنود الأعمال
  DDate      TIMESTAMP Default LOCALTIMESTAMP NOT NULL,                -- التاريخ
  Hours      NUMERIC(5,2) Default 0 NOT NULL,               -- عدد الساعات
  SPrice     NUMERIC(25,2) Default 0 NOT NULL,              -- سعر البيع
  CPrice     NUMERIC(25,2) Default 0 NOT NULL,              -- سعر التكلفة
  SCurn_Id    BIGINT Default 1 NOT NULL,                -- العملة
  SCurn_Rate  NUMERIC(25,9) Default 1,                      -- سعر الصرف
  CCurn_Id    BIGINT Default 1 NOT NULL,                -- العملة
  CCurn_Rate  NUMERIC(25,9) Default 1,                      -- سعر الصرف
  CAmt       NUMERIC(25,2) Default 0 NOT NULL,              -- القيمة قطع = Hours * SPrice 
  Amt        NUMERIC(25,2) Default 0 NOT NULL,              -- القيمة = Hours * SPrice * SCurn_Rate
  CCst       NUMERIC(25,2) Default 0 NOT NULL,              -- الكلفة قطع = Hours * CPrice 
  Cst        NUMERIC(25,2) Default 0 NOT NULL,              -- الكلفة = Hours * CPrice * CCurn_Rate
  Rem        VARCHAR(250),                           -- ملاحظات
  Ins_User   BIGINT, Ins_Date     TIMESTAMP,
  Upd_User   BIGINT, Upd_Date     TIMESTAMP,
  CONSTRAINT Proj_Proj_TSheet_PK           PRIMARY KEY (Id)
);

CREATE SEQUENCE IF NOT EXISTS Proj_Proj_Expense_Seq
  INCREMENT BY 1
  START WITH 1;

CREATE TABLE Proj_Proj_Expense                          -- مصاريف مشروع
( Id          BIGINT NOT NULL,                          -- PK
  Proj_Id     BIGINT NOT NULL,                          -- المشروع
  Serv_Id     BIGINT NOT NULL,                          -- الخدمة
  Curn_Id     BIGINT Default 1 NOT NULL,                -- العملة
  Curn_Rate   NUMERIC(15,7) Default 1 NOT NULL,             -- سعر الصرف
  DDate       TIMESTAMP NOT NULL,                               -- التاريخ
  Qnt         NUMERIC(25,3) Default 0 NOT NULL,             -- الكمية
  Price       NUMERIC(25,2) Default 0 NOT NULL,             -- السعر
  CAmt        NUMERIC(25,2) Default 0 NOT NULL,             -- القيمة قطع = Qnt * Price * Curn_Rate
  Amt         NUMERIC(25,2) Default 0 NOT NULL,             -- القيمة = Qnt * Price
  Billable_Id BIGINT Default 1 NOT NULL,                -- هل يتم فوترة الزبون بها
  Billed_Id   BIGINT Default 0 NOT NULL,                -- هل تم فوترتها؟
  Rem         VARCHAR(100),                          -- ملاحظات
  Ins_User    BIGINT, Ins_Date     TIMESTAMP,
  Upd_User    BIGINT, Upd_Date     TIMESTAMP,
  CONSTRAINT  Proj_Proj_Expense_PK          PRIMARY KEY (Id)
);

CREATE SEQUENCE IF NOT EXISTS Proj_MInv_Seq
  INCREMENT BY 1
  START WITH 1;

Create Table Proj_MInv                               -- فواتير القضية
( Id         BIGINT,                                    -- PK
  Period_Id  BIGINT Default 0,                          -- الفترة المالية
  Status_Id  BIGINT Default 0,                          -- حالة الفاتورة
  Cust_Id    BIGINT Default 0,                          -- الزبون (يؤخذ من القضية عادة)
  Num        BIGINT Default 0,                         -- الرقم
  dDate      TIMESTAMP Default LOCALTIMESTAMP,                         -- التاريخ
  DueDate    TIMESTAMP,                                         -- تاريخ الاستحقاق
  Paid_Id    BIGINT Default 0 NOT NULL,                 -- حالة الدفع
  Paid_Amt   NUMERIC(25,2) Default 0 NOT NULL,              -- المبلغ المدفوع
  Paid_Date  TIMESTAMP,                                         -- تاريخ التسديد
  Rem        VARCHAR(250),                           -- ملاحظات
  Ins_User   BIGINT, Ins_Date     TIMESTAMP,
  Upd_User   BIGINT, Upd_Date     TIMESTAMP,
  CONSTRAINT Proj_Inv_PK        Primary Key (Id),
  CONSTRAINT Proj_Inv_UK        Unique      (Period_Id, Num)
);

CREATE SEQUENCE IF NOT EXISTS Proj_TInv_Seq
  INCREMENT BY 1
  START WITH 1;

Create Table Proj_TInv                               -- بنود فاتورة القضية
( Id           BIGINT NOT NULL,                        -- PK
  Mst_Id       BIGINT NOT NULL,                         -- الفاتورة
  Proj_Id      BIGINT NOT NULL,                         -- المشروع
  TSheet_Id    BIGINT,                                  -- العمل المنفذ على المشروع
  Type_Id      BIGINT Default 1,                        -- النوع + أو -
  Unit_Id      BIGINT Default 0,                        -- الوحدة
  nOrd         SMALLINT Default 0,                        -- الترتيب
  Curn_Id      BIGINT Default 1,                        -- العملة
  Curn_Rate    NUMERIC(25,9) Default 1,                     -- سعر الصرف
  Qnt          NUMERIC(25,3) Default 0 NOT NULL,            -- الكمية
  Price        NUMERIC(25,2) Default 0,                     -- السعر
  CAmt         NUMERIC(25,2) Default 0,                     -- القيمة قطع = Qnt * Price * Curn_Rate
  Amt          NUMERIC(25,2) Default 0,                     -- القيمة = Qnt * Price
  Rem          VARCHAR(250),                         -- ملاحظات
  Ins_User     BIGINT,  Ins_Date  TIMESTAMP,
  Upd_User     BIGINT,  Upd_Date  TIMESTAMP,
  CONSTRAINT Proj_TInv_PK        Primary Key (Id)
);
